  "<div class=\"ach-top\">\n      <label class=\"field\">Titul <select id=\"achTitle\"><option value=\"\">— bez titulu —</option>{0}</select></label>\n      <div><span class=\"eyebrow\">Farba lode {1}</span><div class=\"skins\" style=\"margin-top:6px\">{2}</div></div>\n    </div>\n    <div class=\"ach-grid\">{3}</div>": "<div class=\"ach-top\">\n      <label class=\"field\">Title <select id=\"achTitle\"><option value=\"\">— no title —</option>{0}</select></label>\n      <div><span class=\"eyebrow\">Ship color {1}</span><div class=\"skins\" style=\"margin-top:6px\">{2}</div></div>\n    </div>\n    <div class=\"ach-grid\">{3}</div>",
